sp_widget.client_script:
api.controller = function($scope, $sce) {

    console.log("✅ Widget Loaded");

    $scope.searchText = "";
    $scope.comments = [];
    $scope.newComment = "";

    if ($scope.data.articles && $scope.data.articles.length > 0) {
        setSelected($scope.data.articles[0]);
    }

    function setSelected(article) {
        $scope.selectedArticle = article;
        $scope.trustedText = $sce.trustAsHtml(article.text);

        loadComments(article.sys_id);
    }

    $scope.selectArticle = function(article) {
        setSelected(article);
    };

    // ✅ Load comments
    function loadComments(articleId) {

        $scope.server.update({
            article_id: articleId
        }).then(function(res) {

            console.log("Comments loaded:", res.comments);

            $scope.comments = res.comments || [];
        });
    }

    // ✅ Add comment
    $scope.addComment = function() {

        console.log("👉 Submit clicked");

        if (!$scope.newComment) return;

        $scope.server.update({
            action: "addComment",
            article_id: $scope.selectedArticle.sys_id,
            comment: $scope.newComment
        }).then(function(res) {

            console.log("✅ Added:", res);

            $scope.newComment = "";

            loadComments($scope.selectedArticle.sys_id);
        });
    };

};
``

sp_widget.css:
/* MAIN */
.kb-main {
  display: flex;
  flex-direction: column;
  height: 100%;
}


/* HEADER */
.kb-top-header {
  display: flex;
  align-items: center;
  justify-content: center;   /* ✅ center everything horizontally */
  position: relative;        /* ✅ needed for logo positioning */
  padding: 20px;
  background: #1f2d3d;
  color: white;
  border-bottom: 3px solid #00c4a7;
}

/* LOGO (left, but bigger) */
.kb-header-left {
  position: absolute;   /* ✅ keeps logo at left */
  left: 20px;
}

.kb-logo {
  width: 100px;   /* ✅ increased size */
  height: auto;
}

/* TEXT CENTER */
.kb-header-center {
  text-align: center;
}

.kb-header-center h1 {
  margin: 0;
  font-size: 26px;   /* ✅ slightly bigger */
  font-weight: 600;
}

.kb-header-center p {
  margin: 5px 0 0 0;
  font-size: 14px;
  color: #ccc;
}


/* LAYOUT */
.kb-wrapper {
  display: flex;
  flex: 1;
}

/* LEFT */
.kb-left {
  width: 30%;
  background: #fafafa;
  border-right: 1px solid #ddd;
  display: flex;
  flex-direction: column;
}

.kb-search {
  padding: 10px;
  border-bottom: 1px solid #ddd;
}

.no-results {
  padding: 10px;
  color: #888;
}

/* LIST */
.kb-list {
  list-style: none;
  margin: 0;
  padding: 0;
  overflow-y: auto;
}

.kb-list li {
  padding: 10px;
  cursor: pointer;
  border-bottom: 1px solid #eee;
}

.kb-list li:hover {
  background: #f1f1f1;
}

.kb-list li.active {
  background-color: #1663d6;
  color: white;
  font-weight: bold;
}

/* RIGHT */
.kb-right {
  width: 70%;
  padding: 20px;
}

.kb-header {
  border-bottom: 2px solid #eee;
  margin-bottom: 10px;
}

.kb-number {
  color: #777;
  font-size: 13px;
}

.kb-content {
  line-height: 1.6;
}

/* COMMENTS */
.kb-comments {
  margin-top: 30px;
  border-top: 2px solid #eee;
  padding-top: 15px;
}

.comment-box {
  background: #f8f9fa;
  padding: 10px;
  border-radius: 5px;
  margin-bottom: 10px;
}

.comment-date {
  font-size: 12px;
  color: #888;
}

.add-comment textarea {
  margin-bottom: 10px;
}
``

sp_widget.script:
(function() {

    data.articles = [];
    data.comments = [];

    // ✅ Fetch Articles
    var gr = new GlideRecord('kb_knowledge');
    gr.addEncodedQuery('kb_knowledge_base=76080c0b83c503d0f595ffd6feaad3dd');
    gr.setLimit(50);
    gr.query();

    while (gr.next()) {
        data.articles.push({
            sys_id: gr.getUniqueValue(),
            number: gr.number.toString(),
            title: gr.short_description.toString(),
            text: gr.text.toString()
        });
    }

    // ✅ ADD COMMENT (FIXED)
    if (input && input.action == "addComment") {

        gs.info("🔥 Adding KB Comment");

        var fb = new GlideRecord('kb_feedback');
        fb.initialize();

        fb.article = input.article_id;

        // ✅ CRITICAL FIX
        fb.comments = input.comment;   // ✅ journal write (IMPORTANT)

        fb.rating = 0;

        // ✅ your user
        fb.user = "c9af480f830903d0f595ffd6feaad3a8";

        fb.anonymous = true;

        var rec = fb.insert();

        gs.info("✅ Inserted: " + rec);

        data.status = "inserted";
    }

    // ✅ FETCH COMMENTS (FIXED)
    if (input && input.article_id) {

        var fb2 = new GlideRecord('kb_feedback');
        fb2.addQuery('article', input.article_id);
        fb2.orderByDesc('sys_created_on');
        fb2.query();

        while (fb2.next()) {

            // ✅ CRITICAL FIX for journal field
            var commentText = fb2.getDisplayValue('comments');

            data.comments.push({
                comment: commentText,
                date: fb2.getDisplayValue('sys_created_on')
            });
        }
    }

})();
``
